  // ---- Section 4: No-Limit move tweaks ----------------------------------
  // MistressDMC: height restriction removal
  // Flips each height-gate jb (0F 82) -> je (0F 84) so the move fires at any
  // height (covers Snatch height, Buster, Calibur, Ex-Calibur, Nero Rave,
  // Split/Double-Down, and Dante's air check).
  addPatch("No Height Limit","Remove height restriction (all moves)",
    {{0x4D7D3E,{0x0F,0x84},{0x0F,0x82}},   // dante air check
     {0x513644,{0x0F,0x84},{0x0F,0x82}},   // snatch
     {0x5137D0,{0x0F,0x84},{0x0F,0x82}},   // ex-calibur
     {0x5136AC,{0x0F,0x84},{0x0F,0x82}},   // buster
     {0x513762,{0x0F,0x84},{0x0F,0x82}},   // calibur
     {0x51359D,{0x0F,0x84},{0x0F,0x82}},   // nero rave
     {0x5134E9,{0x0F,0x84},{0x0F,0x82}}}); // split / double down

  // (Infinite Air Hike already added near the top of this file -- removed the
  //  duplicate that was showing a second "Infinite Air Hike" in Mobility.)

  // MistressDMC: remove jump-cancel / weapon-switch cooldowns.
  // Replaces each cooldown-timer load (fld dword [reg+off]) with fldz (push
  // +0.0) so the switch / jump-cancel cooldown is always 0 -> no JC limit.
  addPatch("No Limits","Remove Jump-Cancel / Weapon-Switch Limits",
    {{0x539FF1,{0xD9,0xEE,0x90,0x90,0x90,0x90},{0xD9,0x80,0xDC,0x00,0x00,0x00}},   // sword switch
     {0x53A038,{0xD9,0xEE,0x90,0x90,0x90,0x90},{0xD9,0x81,0xDC,0x00,0x00,0x00}},   // gun switch
     {0x53A4BE,{0xD9,0xEE,0x90,0x90,0x90,0x90},{0xD9,0x81,0x3C,0x01,0x00,0x00}}}); // JC cooldown

  // MistressDMC: Disable Darkslayer directional inputs (Vergil) -- NOP cmp [eax+7],bl
